SELECT p.id AS position_id, e.atr_at_signal AS atr_1m, f.id AS five_id, f.generated_at AS five_generated, f.decision AS five_decision, f.atr_at_signal AS atr_5m, f.atr_percent AS atr_pct_5m, f.final_entry_allowed, f.atr_immediate_entry_allowed, f.atr_recommended_position_percent FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal e ON e.id = p.signal_id JOIN crypto_ai.trade_signal f ON f.id = (SELECT x.id FROM crypto_ai.trade_signal x WHERE x.symbol = p.symbol AND x.interval_code = '5m' AND x.generated_at <= DATE_ADD(e.generated_at, INTERVAL 2 SECOND) ORDER BY x.generated_at DESC LIMIT 1) WHERE p.id IN (182,172,162,158,143,137) LIMIT 6